import openpyxl
from openpyxl.utils import get_column_letter
wb=openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
d=wb['Data']
for r in range(15, 23):
    row=[d.cell(row=r,column=c).value for c in range(1, 16)]
    if any(v is not None for v in row):
        print('Row', r, row)

# Also check which row contains years by scanning rows 1-25 for 2020
for r in range(1, 41):
    for c in range(1, 26):
        if d.cell(row=r,column=c).value==2020:
            print('Found 2020 at', get_column_letter(c)+str(r))
wb.close()
